import{_ as l,l as i,o as e,c as n,v as r,p as s,x as t,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"道德风险与隐藏行动","description":"","frontmatter":{"title":"道德风险与隐藏行动","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/moral-hazard.md","filePath":"econ/moral-hazard.md","lastUpdated":1789023840000}'),m={name:"econ/moral-hazard.md"};function h(A,a,c,_,B,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="道德风险与隐藏行动" tabindex="-1">道德风险与隐藏行动 <a class="header-anchor" href="#道德风险与隐藏行动" aria-label="Permalink to &quot;道德风险与隐藏行动&quot;">​</a></h1><div class="epigraph"><p>保险一旦买下，被保险人减少预防的激励；可观察的是结果，不是行动，合同只能写在结果上。</p><footer>—— 据 Arrow, Uncertainty and the Welfare Economics of Medical Care, AER, 1963；Pauly, AER, 1968；Holmström, Bell Journal, 1979 整理</footer></div><p><a href="/econ/rs-unraveling">上一课</a>（Rothschild–Stiglitz 崩溃）。的类型在签约前已经存在，菜单筛的是隐藏信息。缺口是时序：签约时双方对称，之后一方选不可观察、不可验证的行动，结果是行动加噪声。买方看不见努力，只能看见产出或损失，合同必须写在结果上。这会扭曲努力，即使没有逆向选择。本课钉隐藏行动，下一课把委托–代理的 IC–IR 写全。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>行动 \\(a\\) 进入结果分布 \\(F(x\\mid a)\\)，进入行动者的成本 \\(c(a)\\)。若 \\(a\\) 可写入合同，第一最佳是风险分担加有效努力：风险中性的委托人承担全部风险，代理人拿固定工资，努力用强制规定。隐藏行动后，固定工资使代理人选最省力的 \\(a\\)。要诱出努力，支付必须随 \\(x\\) 变，从而把风险塞给厌恶风险的代理人。</p><p>这与柠檬不同：质量不是事先的类型，而是事后的选择。保险里，保了全险，预防的私人收益下降，事故概率上升——Pauly 把 Arrow 的福利命题收成激励。事故多了，不是因为「坏人买保险」（那是逆向选择），而是因为「买了之后少预防」。</p><h3 id="可观察不等于可验证" tabindex="-1">可观察不等于可验证 <a class="header-anchor" href="#可观察不等于可验证" aria-label="Permalink to &quot;可观察不等于可验证&quot;">​</a></h3><p>法庭要能执行，变量须可验证。委托人自己看见 \\(a\\) 但法庭看不见，仍不能把 \\(a\\) 写进合同。信息经济学的约束是合同集合，不是认知。噪声 \\(x\\) 可验证，所以激励只能通过 \\(x\\) 走。</p><p><span class="marginnote">Holmström 的充分统计：若 \\(x\\) 是 \\(a\\) 的充分统计，其他无关信号不应进入支付，以免无谓风险。似然比 \\(f_a/f\\) 决定哪一个结果该奖、该罚。单调似然比让支付对 \\(x\\) 单调，但不是定理的一般结论。</span></p><p>风险中性且无财富约束时，把随机剩余卖给代理人，IC 自动满足，隐藏行动不造成效率损失。 厌恶风险或有限责任让这一步做不成，才有后课的规划。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：一个代理人，行动在实区间或 \\(\\{低,高\\}\\)，结果有限。合同 \\(w(x)\\)。代理人选 \\(a\\) 最大化 \\(\\mathbb{E}[u(w(x))\\mid a]-c(a)\\)。委托人预见到这个选择，设计 \\(w\\) 最大化自己的期望利润。两行动时，诱出高努力的关键是让高努力的期望效用不低于低努力——这是下一课的激励相容，本课先认清约束来源：分布对 \\(a\\) 的敏感度。</p><p>若代理人风险中性且财富不约束，可把剩余全部卖给他（特许经营），隐藏行动不造成效率损失。风险厌恶或有限责任让这一步做不成，才有风险分担与激励的权衡。</p>',13)),(e(),s(p,null,{default:t(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCR%5B%22%E7%AD%9B%E9%80%89%EF%BC%9A%E7%AD%BE%E7%BA%A6%E5%89%8D%E9%9A%90%E8%97%8F%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20MH%5B%22%E7%AD%BE%E7%BA%A6%E5%90%8E%E9%9A%90%E8%97%8F%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20MH%20--%3E%20X%5B%22%E5%90%88%E5%90%8C%E5%8F%AA%E8%83%BD%E5%86%99%E5%9C%A8%20x%20%E4%B8%8A%22%5D%0A%20%20X%20--%3E%20RISK%5B%22%E6%BF%80%E5%8A%B1%20%3D%20%E6%8A%8A%E9%A3%8E%E9%99%A9%E5%A1%9E%E7%BB%99%E4%BB%A3%E7%90%86%E4%BA%BA%22%5D%0A%20%20RISK%20--%3E%20PA%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AIC%20%E4%B8%8E%20IR%20%E5%86%99%E6%88%90%E8%A7%84%E5%88%92%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>激励来自似然比：某个 \\(x\\) 在高努力下相对更常出现，就应在该 \\(x\\) 上奖。噪声大，似然比平，激励贵，最优可能放弃高努力。这与柠檬的「价格切断类型」不同，这里没有类型分布被切断，而是行动的一阶条件被保险压平。签约时若信息对称，IR 可以抽干事前租金；扭曲全来自事后的隐藏行动，不是来自签约前的信息优势。</p><p>全保险是极限：支付不随 \\(x\\) 变，努力的边际私人收益为零。免赔额、共保是把似然比信息局部地写回合同，用一部分风险换一部分预防。下一课把「选 \\(w(\\cdot)\\) 使代理人愿意选 \\(a_H\\)」写成带乘子的规划，似然比会显式出现在工资公式里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>隐藏类型加隐藏行动同时存在时，合同既筛又激励，远更难。多代理人要相对绩效（Holmström 团队），共同冲击可过滤。行动若部分可观察，应写入一切有信息的可验证变量。也不要把道德风险写成「人变坏」；它是合同集合受限下的最优反应。</p><p>团队生产里共同产出不可分到个人，相对绩效才能滤公共噪声；那是 Holmström 1982，本课只钉单代理人。</p><p>后课默认：隐藏行动 = 结果合同 + 风险–激励权衡；第一最佳在风险中性且无财富约束时可恢复。</p><h3 id="免赔、共保与有限责任" tabindex="-1">免赔、共保与有限责任 <a class="header-anchor" href="#免赔、共保与有限责任" aria-label="Permalink to &quot;免赔、共保与有限责任&quot;">​</a></h3><p>全保险把支付与损失脱钩，预防的私人收益消失。免赔额把似然比集中在是否出险；共保让支付随损失连续分担。两者都是 \\(w(x)\\) 的参数化，不是新的解概念。有限责任把 \\(w\\) 的下界钉住时，即使风险中性也买不回第一最佳，特许经营做不成。似然比高的结果应奖、低的应罚；噪声大则激励贵，最优可能放弃高努力。</p><p>Holmström 的充分统计：若 \\(x\\) 已是 \\(a\\) 的充分统计，再加无关噪声只增加无谓风险。相对绩效用别人的产出过滤共同冲击。团队生产里共同产出不可分到个人，那是 1982 年的另文，本课只钉单代理人。</p><p><span class="marginnote">可观察不等于可验证。委托人看见 \\(a\\) 但法庭看不见，仍不能把 \\(a\\) 写进合同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隐藏行动发生在签约后；合同只能以可验证结果为条件。</li><li>激励要求支付随结果变，与风险分担冲突。</li><li>逆向选择是隐藏类型；两者不要混。</li><li>风险中性加可转让剩余，可回到第一最佳。</li><li>出处：Arrow, <em>AER</em> 1963；Pauly, <em>AER</em> 1968；Holmström, <em>Bell</em> 1979。</li></ul>',13))])}const b=l(m,[["render",h]]);export{f as __pageData,b as default};
